from ortools.sat.python import cp_model
from ortools.constraint_solver import pywrapcp, routing_enums_pb2
import math
import json

def euclidean_distance(coord1, coord2):
    return math.sqrt((coord1[0] - coord2[0])**2 + (coord1[1] - coord2[1])**2)

def main():
    model = cp_model.CpModel()

    K = [0, 1, 2]
    coord_k = {0: (30, 30), 1: (70, 50), 2: (50, 70)}
    setup_cost = {0: 1000, 1: 1200, 2: 1500}
    capacity = {0: 80, 1: 90, 2: 100}

    N = list(range(10))
    coord_n = {
        0: (25, 35), 1: (45, 65), 2: (65, 25), 3: (85, 75), 4: (15, 85),
        5: (75, 15), 6: (35, 55), 7: (55, 45), 8: (95, 35), 9: (25, 75)
    }
    demand = {0: 15, 1: 12, 2: 18, 3: 10, 4: 14, 5: 16, 6: 13, 7: 11, 8: 17, 9: 19}

    vehicle_cap = 40
    vehicle_fixed_cost = 200
    transport_cost_per_km = 8

    total_demand = sum(demand.values())
    V_max = math.ceil(total_demand / vehicle_cap)

    dist_kn = {(k, i): euclidean_distance(coord_k[k], coord_n[i]) for k in K for i in N}
    dist_nn = {(i, j): euclidean_distance(coord_n[i], coord_n[j]) for i in N for j in N if i != j}

    open_var = {k: model.NewBoolVar(f"open_{k}") for k in K}
    assign = {(i, k): model.NewBoolVar(f"assign_{i}_{k}") for i in N for k in K}
    route_assign = {(i, k, v): model.NewBoolVar(f"ra_{i}_{k}_{v}")
                    for i in N for k in K for v in range(V_max)}
    vehicle_used = {(k, v): model.NewBoolVar(f"vu_{k}_{v}")
                    for k in K for v in range(V_max)}
    x = {(i, j, k, v): model.NewBoolVar(f"x_{i}_{j}_{k}_{v}")
         for i in N for j in N if i != j for k in K for v in range(V_max)}
    y_out = {(k, i, v): model.NewBoolVar(f"yo_{k}_{i}_{v}")
             for k in K for i in N for v in range(V_max)}
    y_in = {(k, i, v): model.NewBoolVar(f"yi_{k}_{i}_{v}")
            for k in K for i in N for v in range(V_max)}

    for i in N:
        model.Add(sum(assign[(i, k)] for k in K) == 1)

    for k in K:
        model.Add(sum(demand[i] * assign[(i, k)] for i in N) <= capacity[k] * open_var[k])

    for i in N:
        for k in K:
            model.Add(assign[(i, k)] <= open_var[k])

    for i in N:
        for k in K:
            model.Add(assign[(i, k)] == sum(route_assign[(i, k, v)] for v in range(V_max)))

    for k in K:
        for v in range(V_max):
            for i in N:
                model.Add(vehicle_used[(k, v)] >= route_assign[(i, k, v)])
            model.Add(vehicle_used[(k, v)] <= sum(route_assign[(i, k, v)] for i in N))
            model.Add(vehicle_used[(k, v)] <= open_var[k])
            model.Add(sum(demand[i] * route_assign[(i, k, v)] for i in N) <= vehicle_cap * vehicle_used[(k, v)])

    for i in N:
        for k in K:
            for v in range(V_max):
                left = [y_out[(k, i, v)]] + [x[(j, i, k, v)] for j in N if j != i]
                right = [y_in[(k, i, v)]] + [x[(i, j, k, v)] for j in N if j != i]
                model.Add(sum(left) == route_assign[(i, k, v)])
                model.Add(sum(right) == route_assign[(i, k, v)])

    for k in K:
        for v in range(V_max):
            model.Add(sum(y_out[(k, i, v)] for i in N) == vehicle_used[(k, v)])
            model.Add(sum(y_in[(k, i, v)] for i in N) == vehicle_used[(k, v)])

    for i in N:
        for j in N:
            if i != j:
                for k in K:
                    for v in range(V_max):
                        model.Add(x[(i, j, k, v)] <= route_assign[(i, k, v)])
                        model.Add(x[(i, j, k, v)] <= route_assign[(j, k, v)])

    big_M = len(N) + 1
    u = {(i, k, v): model.NewIntVar(0, big_M, f"u_{i}_{k}_{v}")
         for i in N for k in K for v in range(V_max)}
    for i in N:
        for j in N:
            if i != j:
                for k in K:
                    for v in range(V_max):
                        model.Add(u[(i, k, v)] - u[(j, k, v)] + big_M * x[(i, j, k, v)] <= big_M - 1)
    for i in N:
        for k in K:
            for v in range(V_max):
                model.Add(u[(i, k, v)] <= big_M * route_assign[(i, k, v)])

    SCALE = 1000
    setup_terms = [int(setup_cost[k] * SCALE) * open_var[k] for k in K]
    vehicle_terms = [int(vehicle_fixed_cost * SCALE) * vehicle_used[(k, v)]
                     for k in K for v in range(V_max)]
    transport_terms = []
    for k in K:
        for i in N:
            for v in range(V_max):
                d = int(round(transport_cost_per_km * dist_kn[(k, i)] * SCALE))
                transport_terms.append(d * y_out[(k, i, v)])
                transport_terms.append(d * y_in[(k, i, v)])
    for i in N:
        for j in N:
            if i != j:
                for k in K:
                    for v in range(V_max):
                        d = int(round(transport_cost_per_km * dist_nn[(i, j)] * SCALE))
                        transport_terms.append(d * x[(i, j, k, v)])

    model.Minimize(sum(setup_terms) + sum(vehicle_terms) + sum(transport_terms))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 60.0
    solver.parameters.num_search_workers = 8
    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        opened_kitchens = [k for k in K if solver.Value(open_var[k]) == 1]

        delivery_routes = []
        for k in K:
            for v in range(V_max):
                if solver.Value(vehicle_used[(k, v)]) == 1:
                    nbhoods = [i for i in N if solver.Value(route_assign[(i, k, v)]) == 1]
                    if nbhoods:
                        meals = sum(demand[i] for i in nbhoods)
                        delivery_routes.append([k, nbhoods, meals])

        total_cost = sum(setup_cost[k] for k in opened_kitchens)
        total_cost += vehicle_fixed_cost * sum(
            solver.Value(vehicle_used[(k, v)]) for k in K for v in range(V_max))
        for k in K:
            for i in N:
                for v in range(V_max):
                    if solver.Value(y_out[(k, i, v)]) == 1:
                        total_cost += transport_cost_per_km * dist_kn[(k, i)]
                    if solver.Value(y_in[(k, i, v)]) == 1:
                        total_cost += transport_cost_per_km * dist_kn[(k, i)]
        for i in N:
            for j in N:
                if i != j:
                    for k in K:
                        for v in range(V_max):
                            if solver.Value(x[(i, j, k, v)]) == 1:
                                total_cost += transport_cost_per_km * dist_nn[(i, j)]

        print(json.dumps({
            "opened_kitchens": opened_kitchens,
            "delivery_routes": delivery_routes,
            "total_cost": round(total_cost, 11)
        }))
    else:
        print(json.dumps({"opened_kitchens": [], "delivery_routes": [], "total_cost": 0.0}))

if __name__ == "__main__":
    main()
